{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_4d647567029d7719ab1e8eaf", "claim_ids": ["claim_cc01312d1e404d171bd02c0f", "claim_f8c6ccfd3480589bcee47ac4"], "query_ids": ["q_386"], "claims": [{"claim_id": "claim_cc01312d1e404d171bd02c0f", "quote": "Despite a less than ideal trade climate between the U.S. and China, it remains one of the top sources for hundreds of products.", "url": "https://usacustomsclearance.com/process/importing-lithium-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_f8c6ccfd3480589bcee47ac4", "quote": "Current U.S. policies apply a 54% base tariff on key lithium chemistries, including LFP (lithium iron phosphate) and NMC (nickel manganese cobalt) cells.", "url": "https://manlybattery.com/battery-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "54%"}}]}, {"pair_id": "conflict_ea492c74a3154b84c70fdae6", "claim_ids": ["claim_5d4edd458ed00061c91564c6", "claim_8bd08a843ab502fcac8d7b5e"], "query_ids": ["q_387"], "claims": [{"claim_id": "claim_5d4edd458ed00061c91564c6", "quote": "In the United States, lithium-ion batteries face a combined import tariff exceeding 100%, factoring in base duties, anti-dumping measures, and Section 301 tariffs. In contrast, sodium-ion batteries are currently subject to a total import duty of just 38.4%", "url": "https://www.pknergy.com/news/global-sodium-ion-battery-import-tariff-overview-and-export-strategy", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "38.4%", "reported_policy_status": "currently"}}, {"claim_id": "claim_8bd08a843ab502fcac8d7b5e", "quote": "Sodium-ion batteries have no lithium, cobalt, or nickel – making them entirely insulated from the tariff pressures affecting lithium-based chemistries.", "url": "https://www.totexmfg.com/battery-pack-tariffs-oem-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "insulated from the tariff pressures affecting lithium-based chemistries"}}]}, {"pair_id": "conflict_87c948bce4720d3b351d457a", "claim_ids": ["claim_59d18d1ff90b514d0a0dbf57", "claim_af24ec7e1bc28f018e3eb993"], "query_ids": ["q_388"], "claims": [{"claim_id": "claim_59d18d1ff90b514d0a0dbf57", "quote": "Starting April 2, 2025, the U.S. will implement broad-based tariffs ranging from 10% to 50%. China, South Korea, and Japan are among the countries most affected, particularly China.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "broad-based tariffs ranging from 10% to 50%", "effective_date": "April 2, 2025"}}, {"claim_id": "claim_af24ec7e1bc28f018e3eb993", "quote": "Altogether, this brings the total tariff on Chinese LFP cells to 64.9%, which is set to increase further to 82.4% in 2026 under pre-existing Section 301 tariff escalations introduced by the Biden Administration", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "64.9%", "effective_date": "2026"}}]}, {"pair_id": "conflict_253f0636f5862aff7135947d", "claim_ids": ["claim_59d18d1ff90b514d0a0dbf57", "claim_e9f7d8a23c7c5582aa3523eb"], "query_ids": ["q_388"], "claims": [{"claim_id": "claim_59d18d1ff90b514d0a0dbf57", "quote": "Starting April 2, 2025, the U.S. will implement broad-based tariffs ranging from 10% to 50%. China, South Korea, and Japan are among the countries most affected, particularly China.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "broad-based tariffs ranging from 10% to 50%", "effective_date": "April 2, 2025"}}, {"claim_id": "claim_e9f7d8a23c7c5582aa3523eb", "quote": "Key battery materials such as lithium carbonate, lithium hydroxide, cobalt sulphate, cobalt metal, manganese dioxide, and natural graphite (both powder and flakes) are exempt from these new tariffs.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_340b57f4845e4b4479f50d42", "claim_ids": ["claim_0b17c0b555dae4c53a6637d5", "claim_29502698aa89a49a9e19335e"], "query_ids": ["q_389"], "claims": [{"claim_id": "claim_0b17c0b555dae4c53a6637d5", "quote": "Key battery materials such as lithium carbonate, lithium hydroxide, cobalt sulphate, cobalt metal, manganese dioxide, and natural graphite (both powder and flakes) are exempt from these new tariffs.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_29502698aa89a49a9e19335e", "quote": "Key materials that are not exempt include nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate and synthetic graphite, all of which will be included in the tariff regimes implemented on individual countries.", "url": "https://www.argusmedia.com/en/news-and-insights/latest-market-news/2674679-us-battery-costs-face-sharp-rise-on-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariff regimes implemented on individual countries"}}]}, {"pair_id": "conflict_c83a9178bc303c02f4d68c99", "claim_ids": ["claim_0b17c0b555dae4c53a6637d5", "claim_d4f3f38731b99c4f49614e71"], "query_ids": ["q_389"], "claims": [{"claim_id": "claim_0b17c0b555dae4c53a6637d5", "quote": "Key battery materials such as lithium carbonate, lithium hydroxide, cobalt sulphate, cobalt metal, manganese dioxide, and natural graphite (both powder and flakes) are exempt from these new tariffs.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_d4f3f38731b99c4f49614e71", "quote": "However, several critical materials will be impacted, including nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate, and synthetic graphite. These materials will fall under country-specific tariff regimes.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate, and synthetic graphite"}}]}, {"pair_id": "conflict_4872266b0ff23ad322b87974", "claim_ids": ["claim_29502698aa89a49a9e19335e", "claim_d4f3f38731b99c4f49614e71"], "query_ids": ["q_389"], "claims": [{"claim_id": "claim_29502698aa89a49a9e19335e", "quote": "Key materials that are not exempt include nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate and synthetic graphite, all of which will be included in the tariff regimes implemented on individual countries.", "url": "https://www.argusmedia.com/en/news-and-insights/latest-market-news/2674679-us-battery-costs-face-sharp-rise-on-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariff regimes implemented on individual countries"}}, {"claim_id": "claim_d4f3f38731b99c4f49614e71", "quote": "However, several critical materials will be impacted, including nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate, and synthetic graphite. These materials will fall under country-specific tariff regimes.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate, and synthetic graphite"}}]}, {"pair_id": "conflict_3d9734bf1aa7d64e7b2bdfc2", "claim_ids": ["claim_656c2224370896d2f64b4418", "claim_bc6d0f9330d7a2271ce3e104"], "query_ids": ["q_39"], "claims": [{"claim_id": "claim_656c2224370896d2f64b4418", "quote": "Because definitely all the cars that we would produce here are going to be exempted from any tariffs,” said Hyundai Motor Company CEO Jose Munoz.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai Motor Company", "tariff_program": "exempted from any tariffs"}}, {"claim_id": "claim_bc6d0f9330d7a2271ce3e104", "quote": "Hyundai’s $7.6 billion Georgia plant dodged U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts.", "url": "https://www.teslarati.com/hyundai-georgia-plant-vs-trump-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "U.S. President Donald Trump’s recently announced tariffs on imported vehicles and auto parts", "duty_rate": "25%", "reported_policy_status": "announced"}}]}, {"pair_id": "conflict_eceb78d67b1e2abb489e11ce", "claim_ids": ["claim_66c1dbb2c0b3da72afd80901", "claim_976dd2439991e08fe994131f"], "query_ids": ["q_390"], "claims": [{"claim_id": "claim_66c1dbb2c0b3da72afd80901", "quote": "the tariff rate on Chinese EV lithium-ion batteries saw a sharp increase from 7.5% to 25% in 2024, and was set to reach a combined rate of 173% by April 2025 going forward, only to be put on pause by the same administration that created the executive order to institute them in the first place.", "url": "https://www.acculonenergy.com/resources/navigating-the-tariff-storm-strategies-for-the-u-s-battery-industry-amidst-uncertainty", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "the same administration", "effective_date": "April 2025"}}, {"claim_id": "claim_976dd2439991e08fe994131f", "quote": "For instance, the tariff rate on Chinese EV lithium-ion batteries saw a sharp increase from 7.5% to 25% in 2024", "url": "https://www.acculonenergy.com/resources/navigating-the-tariff-storm-strategies-for-the-u-s-battery-industry-amidst-uncertainty", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "7.5%"}}]}, {"pair_id": "conflict_5e2d1c909880c7855ffe8ab7", "claim_ids": ["claim_03751585484a722c8d2c3c14", "claim_bb58980cda88833ca56356d6"], "query_ids": ["q_391"], "claims": [{"claim_id": "claim_03751585484a722c8d2c3c14", "quote": "Since April 2025, a deal effective August 1, 2025, set tariffs at 15%. The 50% tariff rate on aluminum, steel, and copper products remains in place.", "url": "https://acculonenergy.com/navigating-the-ebb-flow-of-todays-unpredictable-tariff-tides-the-impact-on-the-global-domestic-battery-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%", "effective_date": "August 1, 2025"}}, {"claim_id": "claim_bb58980cda88833ca56356d6", "quote": "Since April 2025, a trade deal effective August 1, 2025, set a 15% tariff rate on Japanese goods. Steel, aluminum, and copper products from Japan remain subject to a 50% tariff rate.", "url": "https://acculonenergy.com/navigating-the-ebb-flow-of-todays-unpredictable-tariff-tides-the-impact-on-the-global-domestic-battery-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "15% tariff rate on Japanese goods", "duty_rate": "15%", "effective_date": "August 1, 2025"}}]}]}

